"""Kaggle entry for Figure 1.

Unpacks the committed scripts/figure1.py (embedded below) and runs it.
The payload must stay byte-identical to scripts/figure1.py.
GPU stays off: this script never requests an accelerator.
Internet is on so MovingMNIST can download. The flow itself is CPU-only.
"""

from __future__ import annotations

import base64
import hashlib
import os
import runpy
import sys
import tempfile
from pathlib import Path

SOURCE_SHA256 = "c5e1b75ca9a5372da7790a94283713c5c61e9997c8de782884e2d5861aaafbb6"
PAYLOAD = """"""


def main() -> None:
    raw = base64.b64decode(PAYLOAD)
    digest = hashlib.sha256(raw).hexdigest()
    if digest != SOURCE_SHA256:
        raise RuntimeError(f"embedded figure1.py sha256 {digest} != {SOURCE_SHA256}")
    print(f"figure1.py sha256 {digest}", flush=True)
    print("accelerator: none (CPU only)", flush=True)
    dest = Path(tempfile.mkdtemp(prefix="dl4stg_figure1_"))
    script = dest / "scripts" / "figure1.py"
    script.parent.mkdir(parents=True, exist_ok=True)
    script.write_bytes(raw)
    (dest / "figures").mkdir()
    (dest / "results").mkdir()
    (dest / "src" / "dl4stg").mkdir(parents=True)
    working = Path("/kaggle/working")
    if working.is_dir():
        os.chdir(working)
    sys.path.insert(0, str(dest / "src"))
    runpy.run_path(str(script), run_name="__main__")


if __name__ == "__main__":
    main()
